const body = $input.first().json.body || $input.first().json || {};
const message = (body.message || '').toString().trim();
const sessionId = (body.sessionId || 'admin-session-' + Date.now()).toString();
const conversationId = (body.conversationId || body.sessionId || 'admin-convo-' + Date.now()).toString();
const userId = (body.userId || 'admin-1').toString();
const userName = (body.userName || 'Administrador').toString();
const role = (body.role || 'admin').toString().toLowerCase();
const page = (body.page || '/admin').toString();
const platformSummary = body.platformSummary || {};

let metricsText = '';
if (typeof platformSummary === 'object' && Object.keys(platformSummary).length > 0) {
  metricsText = [
    `Usuarios registrados: ${platformSummary.usersCount ?? 'N/A'}`,
    `Artistas activos: ${platformSummary.artistsCount ?? 'N/A'}`,
    `Categorias activas: ${platformSummary.categoriesCount ?? 'N/A'}`,
    `Solicitudes totales: ${platformSummary.requestsCount ?? 'N/A'}`,
    `Solicitudes pendientes: ${platformSummary.pendingRequestsCount ?? 'N/A'}`,
    `Inconsistencias detectadas: ${platformSummary.issuesCount ?? '0'}`
  ].join(', ');
} else {
  metricsText = 'Instantánea en tiempo real de la base de datos de ArtLink';
}

const rawHistory = Array.isArray(body.history) ? body.history : [];
const history = rawHistory.slice(-8).map((item) => ({
  role: item.role === 'assistant' || item.role === 'model' ? 'assistant' : 'user',
  content: (item.content || item.text || item.message || '').toString().slice(0, 1200)
}));

return [{
  json: {
    message,
    sessionId,
    conversationId,
    userId,
    userName,
    role,
    page,
    metricsText,
    platformSummary,
    history,
    timestamp: new Date().toISOString()
  }
}];

