const input = $input.first().json || {};
const prev = $('Preparar Contexto Administrativo').first().json || {};

if (input.error || input.status === 'error' || input.name === 'Error') {
  return [{
    json: {
      success: false,
      message: 'El agente de IA no pudo procesar la consulta administrativa en este momento. Intenta nuevamente.',
      errorCode: 'AGENT_ERROR',
      retryable: true,
      actions: [{ label: 'Ir al Dashboard', url: '/admin' }],
      quickReplies: ['Resumir estado general', 'Explicar métricas del dashboard']
    }
  }];
}

let rawOutput = '';
if (typeof input.output === 'string' && input.output.trim()) {
  rawOutput = input.output;
} else if (input.output && typeof input.output.text === 'string' && input.output.text.trim()) {
  rawOutput = input.output.text;
} else if (typeof input.text === 'string' && input.text.trim()) {
  rawOutput = input.text;
} else if (typeof input.response === 'string' && input.response.trim()) {
  rawOutput = input.response;
} else if (typeof input.message === 'string' && input.message.trim()) {
  rawOutput = input.message;
} else if (typeof input === 'string' && input.trim()) {
  rawOutput = input;
}
rawOutput = (rawOutput || '').toString();

let cleanMessage = rawOutput;
let actions = [];
let quickReplies = [];

const jsonBlockMatch = rawOutput.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (jsonBlockMatch) {
  try {
    const parsed = JSON.parse(jsonBlockMatch[1].trim());
    if (parsed && typeof parsed === 'object') {
      if (Array.isArray(parsed.actions)) {
        actions = parsed.actions.filter(a => a && typeof a === 'object' && typeof a.label === 'string' && typeof a.url === 'string' && a.url.startsWith('/admin'));
      }
      if (Array.isArray(parsed.quickReplies)) {
        quickReplies = parsed.quickReplies.filter(r => typeof r === 'string' && r.trim().length > 0);
      }
    }
  } catch (e) {}
}

cleanMessage = cleanMessage.replace(/```(?:json)?[\s\S]*?```/g, '').trim();
cleanMessage = cleanMessage.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
cleanMessage = cleanMessage.replace(/<\/?[a-z][a-z0-9]*\b[^>]*>/gi, '');
cleanMessage = cleanMessage.trim();

if (!cleanMessage) {
  cleanMessage = 'No se obtuvo una respuesta detallada del agente administrativo. Por favor reformula la consulta.';
}

if (actions.length === 0) {
  actions = [
    { label: 'Dashboard General', url: '/admin' },
    { label: 'Supervisar Solicitudes', url: '/admin/solicitudes' }
  ];
}

if (quickReplies.length === 0) {
  quickReplies = [
    'Resumir estado general',
    'Explicar métricas del dashboard',
    'Detectar problemas o inconsistencias'
  ];
}

return [{
  json: {
    success: true,
    message: cleanMessage,
    actions,
    quickReplies,
    provider: 'gemini-n8n',
    model: 'gemini-3.1-flash-lite',
    sessionId: prev.sessionId,
    timestamp: new Date().toISOString()
  }
}];
